SET NAMES utf8mb4;

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'نخستین معاینهٔ دندان و برنامه‌ریزی جامع درمان',
'<p>معاینهٔ نخستِ جامع یعنی شنیدن شکایت، گرفتن سابقهٔ پزشکی و دندانی، ارزیابی بالینی دهان و بافت‌های پیرامون و تفسیر هم‌زمان تنها ثبت‌هایی که لازم دیده می‌شوند. برنامهٔ درمان بر پایهٔ این یافته‌ها، اولویت‌های بیمار و گزینه‌های مناسب، مرحله‌به‌مرحله تدوین می‌شود.</p>
<p><img src="/assets/uploads/images/ts18-ilk-dis-muayenesi-gorusme.webp" alt="شنیدن علت مراجعه و انتظارهای بیمار در نخستین معاینه" loading="lazy"  /></p>
<h2>علت مراجعه و انتظارها</h2>
<p>درد، انتظار زیبایی، دشواری جویدن، دندان از دست‌رفته، ترمیم‌های موجود و اولویت‌ها با بیان خود بیمار ثبت می‌شوند. هدف نخست تنها برگزیدن یک اقدام نیست؛ فهمیدن نیازها و معیارهای تصمیم است.</p>
<h2>سابقهٔ پزشکی و دندانی</h2>
<p>بیماری‌های زمینه‌ای، حساسیت‌ها، احتمال بارداری، جراحی‌ها و درمان‌های پیشین، داروهای مصرفی و تجربه‌های دندانی گذشته پرسیده می‌شود. در صورت نیاز نظر پزشک معالج بیمار گرفته می‌شود؛ بیمار داروهایش را به تصمیم خود قطع نمی‌کند. برای برنامه‌ریزی درمان در بارداری می‌توانید به صفحهٔ <a href="/fa/hamilelikte-dis-tedavisi/">درمان دندان در بارداری</a> نگاه کنید.</p>
<h2>معاینهٔ خارج دهانی و بافت نرم</h2>
<p>تقارن چهره، حرکات فک، غدد لنفاوی و یافته‌های لازم خارج دهانی؛ و بافت‌های نرم مانند لب، گونه، زبان، کام و کف دهان به‌صورت نظام‌مند ارزیابی می‌شوند. اگر یافته‌ای مشکوک دیده شود، ارزیابی پیشرفته و آزمون‌های لازم برنامه‌ریزی می‌گردد.</p>
<h2>دندان‌ها و ترمیم‌های موجود</h2>
<p>گمان به <a href="/fa/dis-curugu-kompozit-dolgu/">پوسیدگی</a>، شکستگی و سایش، تغییر رنگ، حساسیت، لقی دندان، وضعیت ترمیم‌ها، روکش‌ها و بریج‌ها و نواحی دندان از دست‌رفته با یافته‌های بالینی ارزیابی می‌شوند. در صورت نیاز آزمون‌های حیات و دیگر آزمون‌های کمکی افزوده می‌گردد.</p>
<p><img src="/assets/uploads/images/ts18-kapsamli-agiz-dis-muayenesi.webp" alt="معاینهٔ نظام‌مند دندان‌ها، لثه و بافت‌های دهان" loading="lazy"  /></p>
<h2>ارزیابی لثه و پریودنتال</h2>
<p>پلاک و جرم، خون‌ریزی، تحلیل لثه، عمق پاکت، بافت‌های پشتیبان و نشانگرهای خطر ارزیابی می‌شوند. سلامت لثه می‌تواند ترتیب درمان را پیش از اقدام‌های ایمپلنت، پروتتیک یا زیبایی تغییر دهد.</p>
<h2>داده‌های معاینه چگونه با هم به کار می‌روند؟</h2>
<table>
<thead><tr><th>ثبت</th><th>سهم آن</th><th>اصل کاربرد</th></tr></thead>
<tbody>
<tr><td>معاینهٔ بالینی</td><td>یافته‌های دندان، لثه، بافت نرم، مفصل فک و اکلوژن</td><td>ارزیابی پایه که گسترهٔ آن در هر بیمار بر پایهٔ نیاز تعیین می‌شود</td></tr>
<tr><td>ثبت رادیوگرافیک</td><td>ارزیابی ریشه، استخوان و سطوح بین‌دندانی که با چشم دیده نمی‌شوند</td><td>تنها تصویری که بر پایهٔ سابقه، ثبت‌های پیشین و یافتهٔ بالینی لازم است</td></tr>
<tr><td>عکس / اسکن دیجیتال</td><td>ثبتی که به مستندسازی وضعیت آغازین، ردیف دندان‌ها و اکلوژن کمک می‌کند</td><td>بر پایهٔ نوع درمان و نیاز برنامه‌ریزی؛ به‌تنهایی تشخیص قطعی نیست</td></tr>
</tbody>
</table>
<p><strong>مهم:</strong> رادیوگرافی پانورامیک، توموگرافی، عکس یا اسکن دیجیتال برای هر بیمار بسته‌ای خودکار نیست. تاریخ و کفایت تشخیصی ثبت‌های پیشین ارزیابی می‌شود؛ ثبت تازه تنها در صورت ضرورت بالینی گرفته می‌گردد.</p>
<p><img src="/assets/uploads/images/ts18-klinik-radyografik-dijital-degerlendirme.webp" alt="ارزیابی هم‌زمان ثبت‌های بالینی، رادیوگرافیک و دیجیتال" loading="lazy"  /></p>
<h2>اکلوژن، مفصل و عملکرد</h2>
<p>تماس‌های دندانی، رابطهٔ جویدن، بازشدن دهان، شکایت‌های مفصل و عضله، عادت دندان‌قروچه و یافته‌های سایش ارزیابی می‌شوند. هر صدا یا سایشی به‌تنهایی به معنای بیماری یا نیاز به پلاک نیست.</p>
<h2>انتخاب روش تصویربرداری</h2>
<p>رادیوگرافی بایت‌وینگ، پری‌اپیکال، پانورامیک یا تصویربرداری سه‌بعدی بر پایهٔ یافتهٔ معاینه و اقدام برنامه‌ریزی‌شده انتخاب می‌شود. رویکرد توموگرافی برای هر بیمار به کار نمی‌رود؛ سهم تشخیصی مورد انتظار با میزان پرتوگیری با هم سنجیده می‌شود.</p>
<h2>نقش ثبت‌های دیجیتال</h2>
<p>ثبت‌هایی که با اسکنر داخل‌دهانی گرفته می‌شوند، عکس‌های استاندارد و مدل‌های دیجیتال می‌توانند به مستندسازی وضعیت آغازین، اکلوژن و برنامهٔ ترمیمی کمک کنند. خروجی نرم‌افزار جای معاینهٔ دندان‌پزشک و راستی‌آزمایی بالینی را نمی‌گیرد.</p>
<h2>تشخیص و ارزیابی خطر</h2>
<p>پوسیدگی، بیماری لثه، مشکلات پالپ و نوک ریشه، خطر شکستگی، بهداشت، سیگار، تغذیه و عادت‌های مراقبت با هم در نظر گرفته می‌شوند. برای یافته‌هایی که قطعی نمی‌شوند، پیگیری یا آزمون افزوده برنامه‌ریزی می‌گردد.</p>
<h2>برنامهٔ درمان مرحله‌ای</h2>
<ol>
<li>کنترل درد اورژانسی و عفونت</li>
<li>متوقف‌کردن بیماری و سلامت پایهٔ لثه</li>
<li>مراحل ترمیمی، جراحی یا پروتتیک قطعی</li>
<li>مراقبت و فاصلهٔ معاینهٔ تعیین‌شده به‌صورت فردی</li>
</ol>
<p>وضعیت بالینی می‌تواند این ترتیب را تغییر دهد. برای اینکه برنامه چه سرفصل‌هایی دارد و چگونه به‌روز می‌شود می‌توانید به صفحهٔ <a href="/fa/tedavi-plani-ve-surec/">برنامهٔ درمان و روند آن</a> نگاه کنید.</p>
<p><img src="/assets/uploads/images/ts18-asamali-tedavi-plani-ve-bilgilendirme.webp" alt="توضیح برنامهٔ درمان مرحله‌ای برای بیمار" loading="lazy"  /></p>
<h2>گزینه‌ها و روند</h2>
<p>هدف هر گزینهٔ قابل اجرا، سود و خطرهای مهم آن، گزینه‌های جایگزین، پیامدهای احتمالی درمان‌نشدن و مدت و گسترهٔ تقریبی به‌صورت قابل فهم گفت‌وگو می‌شود. برنامه می‌تواند بر پایهٔ یافته‌های بالینی تازه یا پاسخ بهبودی به‌روز شود. رضایت آگاهانه تنها یک امضا نیست؛ روندی از آگاهی‌رسانی روشن و امکان پرسیدن است.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا در نخستین معاینه درمان بی‌درنگ انجام می‌شود؟</strong><br>همیشه نه. اولویت با ارزیابی و برنامه‌ریزی ایمن است. درد اورژانسی یا اقدامی ساده و مناسب در صورت وجود زمان و رضایت می‌تواند همان روز انجام شود. درمان جامع بیشتر اوقات پس از برنامه‌ریزی آغاز می‌گردد.</p>
<p><strong>آیا از هر بیماری رادیوگرافی پانورامیک خواسته می‌شود؟</strong><br>خیر. نوع و زمان تصویربرداری بر پایهٔ سابقه، معاینهٔ بالینی، فیلم‌های پیشین و اقدام برنامه‌ریزی‌شده تعیین می‌شود. اگر ثبت‌های موجود کافی باشند تکرار بی‌مورد انجام نمی‌گیرد.</p>
<p><strong>اولویت در برنامهٔ درمان چگونه تعیین می‌شود؟</strong><br>وضعیت اورژانسی و کنترل عفونت نخست می‌آیند؛ پس از کامل‌شدن مراحل پایه مانند کنترل لثه و پوسیدگی، ترمیم قطعی، ایمپلنت-پروتز یا اقدام‌های زیبایی برنامه‌ریزی می‌شوند.</p>
<p><strong>آیا می‌توانم برای نظر دوم ثبت‌های موجودم را بیاورم؟</strong><br>بله. رادیوگرافی‌ها، گزارش‌ها، اطلاعات ایمپلنت و ثبت‌های درمان پیشین می‌توانند به ارزیابی کمک کنند. اما اگر تازگی یا کیفیت تصویر کافی نباشد ثبت افزوده لازم می‌شود.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، نخستین معاینه به‌عنوان روندی جامع از برنامه‌ریزی در نظر گرفته می‌شود که در آن شکایت، سابقهٔ پزشکی، سلامت دندان و لثه، اکلوژن و تنها ثبت‌های بالینی و دیجیتال لازم با هم ارزیابی می‌گردند.</p>
<p><a href="/fa/acil-dis-agrisinda-ilk-24-saat/">درد اورژانسی دندان</a> &middot; <a href="/fa/tedavi-plani-ve-surec/">برنامهٔ درمان و روند آن</a> &middot; <a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'دربارهٔ سابقهٔ پزشکی، ارزیابی لثه و اکلوژن، رادیوگرافی‌های لازم، ثبت‌های دیجیتال و برنامهٔ درمان مرحله‌ای در نخستین معاینهٔ دندان بدانید.',
'نخستین معاینهٔ دندان و برنامهٔ درمان | MSc. Dt. Mehmet Taş',
'FA' FROM pages WHERE link = 'ilk-dis-muayenesi-tedavi-planlamasi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'برنامهٔ درمان و شفافیت روند: گستره را چه تعیین می‌کند؟',
'<p>در درمان دندان، ابهام بیشتر اوقات نگرانی‌ای بیش از خود درمان پدید می‌آورد. وقتی پس از معاینه به‌صورت کتبی گفته شود کدام اقدام‌ها انجام می‌شوند، در چند مرحله پایان می‌یابند و با چه ترتیبی پیش می‌روند، بیمار تصمیمش را آگاهانه می‌گیرد. این صفحه پیش از مراجعه به کلینیک توضیح می‌دهد روند چگونه کار می‌کند.</p>
<p><img src="/assets/uploads/images/ts90-01-tedavi-plani-gorusmesi.webp" alt="گفت‌وگوی دندان‌پزشک با بیمار دربارهٔ برنامهٔ درمان" loading="lazy"  /></p>
<h2>برنامهٔ درمان چه را در بر می‌گیرد؟</h2>
<table>
<thead><tr><th>بخش</th><th>توضیح</th></tr></thead>
<tbody>
<tr><td>یافته‌های بالینی</td><td>وضعیتی که در پی معاینه و تصویربرداری لازم مشخص شده است.</td></tr>
<tr><td>اقدام‌های پیشنهادی</td><td>برای کدام دندان کدام اقدام پیشنهاد می‌شود، به زبانی روشن.</td></tr>
<tr><td>گزینه‌های جایگزین</td><td>رویکردهای دیگری که برای همان مشکل قابل ارزیابی‌اند و تفاوت‌هایشان.</td></tr>
<tr><td>مراحل و ترتیب</td><td>کدام اقدام باید نخست انجام شود و چرا.</td></tr>
<tr><td>روند تقریبی</td><td>شمار تقریبی جلسه‌ها و دوره‌های انتظار مورد انتظار برای بهبودی.</td></tr>
<tr><td>اگر انجام نشود چه می‌شود؟</td><td>روندی که در صورت به تعویق افتادن درمان انتظار می‌رود.</td></tr>
<tr><td>نیاز به مراقبت</td><td>انتظار معاینه و مراقبت روزانه پس از درمان.</td></tr>
</tbody>
</table>
<p>در برنامه‌های جامع، این اطلاعات افزون بر توضیح شفاهی به‌صورت کتبی نیز ارائه می‌شود؛ بیمار برای اندیشیدن و پرسیدن زمان دارد.</p>
<h2>گسترهٔ برنامه را چه تعیین می‌کند؟</h2>
<p>برنامهٔ درمان دو نفری که با یک شکایت می‌آیند ممکن است یکسان نباشد. عوامل اصلی که گستره را تعیین می‌کنند:</p>
<ul>
<li>نوع مشکل، گستردگی و میزان پیشرفت آن</li>
<li>بافت سالم باقی‌ماندهٔ دندان و وضعیت پشتیبانی لثه و استخوان</li>
<li>رابطهٔ اکلوژن، عادت دندان‌قروچه</li>
<li>وضعیت عمومی سلامت، داروهای مصرفی، مصرف سیگار</li>
<li>عادت‌های بهداشت دهان و امکان آمدن به معاینات</li>
<li>روش انتخاب‌شده، مادهٔ به‌کاررفته و مرحلهٔ آزمایشگاه</li>
<li>نیاز به اقدام‌های آماده‌سازی (درمان لثه، افزایش استخوان، آماده‌سازی ارتودنسی و مانند آن)</li>
</ul>
<p>بدون معاینه نمی‌توان برنامه ساخت. اطلاع قطعی دربارهٔ درمان و گستره که از راه تلفن، پیام یا از روی عکس داده شود قابل اتکا نیست. گفت‌وگوی مقدماتی تنها تصوری کلی می‌دهد؛ برنامه پس از معاینهٔ بالینی و تصویربرداری لازم تدوین می‌شود.</p>
<p><img src="/assets/uploads/images/ts90-03-muayene-ve-degerlendirme.webp" alt="انجام هم‌زمان معاینه و ارزیابی رادیوگرافیک" loading="lazy"  /></p>
<h2>برنامه‌ریزی مرحله‌ای و ترتیب اولویت</h2>
<p>در درمان‌های جامع همه‌چیز هم‌زمان انجام نمی‌شود. ترتیبی که به‌طور کلی دنبال می‌شود چنین است:</p>
<table>
<thead><tr><th>مرحله</th><th>محتوا</th></tr></thead>
<tbody>
<tr><td>۱ — اورژانس</td><td>وضعیت‌هایی که تعویق‌بردار نیستند مانند درد، عفونت، ورم و ضربه.</td></tr>
<tr><td>۲ — متوقف‌کردن بیماری</td><td><a href="/fa/dis-curugu-kompozit-dolgu/">درمان پوسیدگی</a>، درمان لثه، سامان‌دادن بهداشت دهان.</td></tr>
<tr><td>۳ — بازسازی</td><td>ترمیم، روکش، <a href="/fa/kanal-tedavisi/">درمان ریشه</a>، <a href="/fa/dental-implant-tedavisi/">جایگزینی دندان‌های از دست‌رفته</a>.</td></tr>
<tr><td>۴ — زیبایی</td><td>اقدام‌های زیبایی غیرضروری؛ پس از حل مشکل‌های سلامت.</td></tr>
<tr><td>۵ — پیشگیری و پیگیری</td><td>معاینهٔ منظم، تمیزکردن، در صورت نیاز نایت‌گارد.</td></tr>
</tbody>
</table>
<p>هدف این ترتیب آن است که بنیادی که کار بر آن بنا می‌شود استوار باشد. نتیجهٔ بلندمدت ترمیمی زیبایی که هنگام ادامهٔ التهاب لثه انجام شود می‌تواند آسیب ببیند.</p>
<p><img src="/assets/uploads/images/ts90-02-asamali-planlama.webp" alt="نموداری که تقسیم برنامهٔ درمان به مراحل را نشان می‌دهد" loading="lazy"  /></p>
<h2>آیا برنامه می‌تواند تغییر کند؟</h2>
<p>بله. در دندان‌پزشکی برخی یافته‌ها تنها در حین اقدام دیده می‌شوند: برای نمونه عمق پوسیدگی دقیقاً هنگام تمیزکردن آشکار می‌شود و نیاز به درمان ریشه می‌تواند پدید آید. در چنین وضعیت‌هایی پیش از ادامهٔ اقدام به بیمار اطلاع داده و رضایت او گرفته می‌شود. به‌روزشدن برنامه به معنای نادرست‌بودن ارزیابی آغازین نیست.</p>
<h2>سازمان تأمین اجتماعی و درمان‌های دندان</h2>
<p>حق‌های درمان دندان در چارچوب سازمان تأمین اجتماعی بر پایهٔ نوع مرکزی که به آن مراجعه می‌شود تغییر می‌کند. خدمات سلامت دهان و دندان در مراکز درمانی دولتی و در مراکزی که با این سازمان قرارداد دارند، در چارچوب تعریف‌شده در مقررات ارائه می‌گردد.</p>
<p><strong>کلینیک ما با سازمان تأمین اجتماعی قرارداد ندارد.</strong> این اطلاع چون باید پیش از نوبت‌گیری دانسته شود، اینجا آشکارا بیان شده است. اگر مقررات یا وضعیت قرارداد تغییر کند این بخش به‌روز می‌شود.</p>
<h2>پرسش‌هایی که می‌توانید از دندان‌پزشک بپرسید</h2>
<ul>
<li>در وضعیت من کدام اقدام‌ها پیشنهاد می‌شود و چرا؟</li>
<li>گزینه‌های جایگزین این درمان چیست؟ تفاوتشان چیست؟</li>
<li>کدام باید اکنون انجام شود و کدام می‌تواند صبر کند؟</li>
<li>انتظار می‌رود چند جلسه طول بکشد؟ میان جلسه‌ها چقدر فاصله خواهد بود؟</li>
<li>پس از اقدام چه احساسی طبیعی است و در چه وضعیتی باید با شما تماس بگیرم؟</li>
<li>اگر این درمان را انجام ندهم چه می‌شود؟</li>
<li>پس از آن چه نظمی از مراقبت و معاینه لازم است؟</li>
<li>آیا می‌توانم دربارهٔ مادهٔ به‌کاررفته اطلاع بگیرم؟</li>
<li>اگر برنامه در حین درمان تغییر کند چگونه آگاه می‌شوم؟</li>
</ul>
<h2>داده‌های شخصی شما</h2>
<p>اطلاعاتی که در روند معاینه، تصویربرداری و درمان به دست می‌آید دادهٔ شخصی با ماهیت ویژه است. اینکه با چه هدفی پردازش می‌شود، چه مدت نگهداری می‌گردد و چه حقوقی دارید در <a href="/fa/sayfa/kvkk-aydinlatma-metni">متن روشنگری حفاظت از داده‌های شخصی</a> توضیح داده شده است. از طریق فرم نوبت، اطلاعات سلامت تفصیلی یا تصویر خواسته نمی‌شود؛ در موارد لازم روش ایمن جداگانه اعلام می‌گردد.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا می‌توانم گسترهٔ درمان را تلفنی بدانم؟</strong><br>چون گسترهٔ درمان بدون معاینه تعیین نمی‌شود، اطلاع قطعی تلفنی داده نمی‌شود. پس از معاینه برنامهٔ ویژهٔ شما به‌صورت کتبی ارائه می‌گردد.</p>
<p><strong>آیا می‌توانم برای اندیشیدن دربارهٔ برنامهٔ درمان زمان بگیرم؟</strong><br>بله. اگر وضعیت اورژانسی نباشد، اختصاص زمان برای ارزیابی برنامه امری مورد انتظار است. پرسش‌هایتان را می‌توانید بعداً نیز بپرسید.</p>
<p><strong>آیا می‌توانم نظر دندان‌پزشک دیگری را بخواهم؟</strong><br>بله. گرفتن نظر دوم حق بیمار است. در صورت درخواست، ثبت‌های موجود شما ارائه می‌شود.</p>
<p><strong>اگر برنامه در حین درمان تغییر کند چه می‌شود؟</strong><br>پیش از ادامهٔ اقدام وضعیت توضیح داده، گزینه‌ها ارائه و رضایت شما گرفته می‌شود.</p>
<p><strong>هنگام آمدن به نوبت چه بیاورم؟</strong><br>کارت شناسایی، رادیوگرافی‌ها و ثبت‌های درمان پیشین در صورت وجود، فهرست داروهای مصرفی و اطلاعات بیماری یا حساسیت شناخته‌شده. اگر گزارشی از دندان‌پزشک دیگری دارید همراه داشته باشید.</p>
<p><strong>آیا می‌توانم صورتحساب و مدارک بگیرم؟</strong><br>برای اقدام‌های انجام‌شده مستندسازی بر پایهٔ مقررات انجام می‌گیرد. در صورت درخواست، رونوشتی از ثبت‌های درمان شما داده می‌شود.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، برنامهٔ درمان با ارزیابی هم‌زمان معاینهٔ بالینی، تصویربرداری لازم و انتظارهای بیمار تدوین و با او در میان گذاشته می‌شود.</p>
<p><a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a> &middot; <a href="/fa/kanal-tedavisi/">درمان ریشه</a> &middot; <a href="/fa/sayfa/kvkk-aydinlatma-metni">متن روشنگری حفاظت از داده‌های شخصی</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'برنامهٔ درمان چه را در بر می‌گیرد و گسترهٔ آن را چه تعیین می‌کند؟ آنچه باید پیش از نوبت بدانید و پرسش‌هایی که می‌توان پرسید.',
'برنامهٔ درمان و شفافیت روند | MSc. Dt. Mehmet Taş',
